PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "kormi_peran" ("id" varchar not null, "nama_peran" varchar not null, "slug" varchar not null, "deskripsi" varchar, "dibuat_pada" datetime not null default CURRENT_TIMESTAMP, "diperbarui_pada" datetime not null default CURRENT_TIMESTAMP, primary key ("id"));
CREATE TABLE IF NOT EXISTS "kormi_pengguna" ("id" varchar not null, "peran_id" varchar not null, "nama_lengkap" varchar not null, "email" varchar not null, "kata_sandi" varchar not null, "nomor_telepon" varchar, "foto_profil" varchar, "status_aktif" tinyint(1) not null default '1', "terakhir_masuk" datetime, "dibuat_pada" datetime not null default CURRENT_TIMESTAMP, "diperbarui_pada" datetime not null default CURRENT_TIMESTAMP, "dihapus_pada" datetime, foreign key("peran_id") references "kormi_peran"("id") on delete restrict, primary key ("id"));
CREATE TABLE IF NOT EXISTS "kormi_pengaturan_situs" ("id" varchar not null, "kunci_pengaturan" varchar not null, "nilai_pengaturan" text, "kelompok" varchar not null default 'umum', "dibuat_pada" datetime not null default CURRENT_TIMESTAMP, "diperbarui_pada" datetime not null default CURRENT_TIMESTAMP, primary key ("id"));
CREATE TABLE IF NOT EXISTS "kormi_linimasa_sejarah" ("id" varchar not null, "tahun" varchar not null, "judul" varchar not null, "deskripsi" text not null, "gambar_url" varchar, "urutan" integer not null default '0', "status_tampil" tinyint(1) not null default '1', "dibuat_pada" datetime not null default CURRENT_TIMESTAMP, "diperbarui_pada" datetime not null default CURRENT_TIMESTAMP, primary key ("id"));
CREATE TABLE IF NOT EXISTS "kormi_visi_misi" ("id" varchar not null, "jenis" varchar check ("jenis" in ('visi', 'misi', 'nilai_utama', 'motto', 'tujuan')) not null, "konten" text not null, "ikon" varchar, "urutan" integer not null default '0', "status_tampil" tinyint(1) not null default '1', "dibuat_pada" datetime not null default CURRENT_TIMESTAMP, "diperbarui_pada" datetime not null default CURRENT_TIMESTAMP, primary key ("id"));
CREATE TABLE IF NOT EXISTS "kormi_kecamatan" ("id" varchar not null, "nama_kecamatan" varchar not null, "slug" varchar not null, "alamat_kantor" varchar, "nomor_telepon" varchar, "latitude" numeric, "longitude" numeric, "dibuat_pada" datetime not null default CURRENT_TIMESTAMP, "diperbarui_pada" datetime not null default CURRENT_TIMESTAMP, primary key ("id"));
CREATE TABLE IF NOT EXISTS "kormi_desa_kelurahan" ("id" varchar not null, "kecamatan_id" varchar not null, "nama_desa_kelurahan" varchar not null, "slug" varchar not null, "jenis" varchar check ("jenis" in ('desa', 'kelurahan')) not null default 'desa', "dibuat_pada" datetime not null default CURRENT_TIMESTAMP, "diperbarui_pada" datetime not null default CURRENT_TIMESTAMP, foreign key("kecamatan_id") references "kormi_kecamatan"("id") on delete cascade, primary key ("id"));
CREATE TABLE IF NOT EXISTS "kormi_periode_kepengurusan" ("id" varchar not null, "nama_periode" varchar not null, "tahun_mulai" integer not null, "tahun_selesai" integer not null, "status_aktif" tinyint(1) not null default '0', "dibuat_pada" datetime not null default CURRENT_TIMESTAMP, "diperbarui_pada" datetime not null default CURRENT_TIMESTAMP, primary key ("id"));
CREATE TABLE IF NOT EXISTS "kormi_pengurus" ("id" varchar not null, "periode_id" varchar not null, "nama_lengkap" varchar not null, "jabatan" varchar not null, "kategori_bidang" varchar, "foto_url" varchar, "urutan" integer not null default '0', "status_tampil" tinyint(1) not null default '1', "dibuat_pada" datetime not null default CURRENT_TIMESTAMP, "diperbarui_pada" datetime not null default CURRENT_TIMESTAMP, foreign key("periode_id") references "kormi_periode_kepengurusan"("id") on delete cascade, primary key ("id"));
CREATE TABLE IF NOT EXISTS "kormi_kordik_pengurus" ("id" varchar not null, "kecamatan_id" varchar not null, "periode_id" varchar not null, "nama_ketua" varchar not null, "nama_sekretaris" varchar, "nama_bendahara" varchar, "nomor_telepon" varchar, "nomor_sk" varchar, "foto_ketua_url" varchar, "status_aktif" tinyint(1) not null default '1', "dibuat_pada" datetime not null default CURRENT_TIMESTAMP, "diperbarui_pada" datetime not null default CURRENT_TIMESTAMP, foreign key("kecamatan_id") references "kormi_kecamatan"("id") on delete cascade, foreign key("periode_id") references "kormi_periode_kepengurusan"("id") on delete cascade, primary key ("id"));
CREATE TABLE IF NOT EXISTS "kormi_duta_olahraga" ("id" varchar not null, "kecamatan_id" varchar not null, "desa_kelurahan_id" varchar, "nama_lengkap" varchar not null, "tahun_pemilihan" integer not null default '2026', "kategori_duta" varchar not null default 'Duta Olahraga Masyarakat', "gelar_prestasi" varchar, "deskripsi_prestasi" text, "akun_instagram" varchar, "foto_url" varchar, "status_unggulan" tinyint(1) not null default '0', "dibuat_pada" datetime not null default CURRENT_TIMESTAMP, "diperbarui_pada" datetime not null default CURRENT_TIMESTAMP, foreign key("kecamatan_id") references "kormi_kecamatan"("id") on delete restrict, foreign key("desa_kelurahan_id") references "kormi_desa_kelurahan"("id") on delete set null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "kormi_program_kerja" ("id" varchar not null, "tahun_anggaran" integer not null, "nama_bidang" varchar not null, "nama_kegiatan" varchar not null, "tujuan_kegiatan" text, "target_sasaran" varchar, "estimasi_anggaran" numeric, "status_kegiatan" varchar check ("status_kegiatan" in ('rencana', 'berjalan', 'selesai', 'ditunda')) not null default 'rencana', "bulan_mulai" integer, "bulan_selesai" integer, "ikon" varchar not null default 'activity', "dibuat_pada" datetime not null default CURRENT_TIMESTAMP, "diperbarui_pada" datetime not null default CURRENT_TIMESTAMP, primary key ("id"));
CREATE TABLE IF NOT EXISTS "kormi_komisi_inorga" ("id" varchar not null, "nama_komisi" varchar not null, "singkatan" varchar not null, "deskripsi" text, "kode_warna_hex" varchar not null default '#1bb55c', "urutan" integer not null default '0', "dibuat_pada" datetime not null default CURRENT_TIMESTAMP, "diperbarui_pada" datetime not null default CURRENT_TIMESTAMP, primary key ("id"));
CREATE TABLE IF NOT EXISTS "kormi_inorga" ("id" varchar not null, "komisi_id" varchar not null, "nama_inorga" varchar not null, "singkatan" varchar not null, "slug" varchar not null, "nama_ketua" varchar, "kontak_person" varchar, "nomor_telepon" varchar, "email" varchar, "alamat_sekretariat" text, "nomor_sk" varchar, "tanggal_sk" date, "jumlah_klub_anggota" integer not null default '0', "logo_url" varchar, "status_keanggotaan" varchar check ("status_keanggotaan" in ('aktif', 'masa_tenggang', 'tidak_aktif', 'verifikasi')) not null default 'aktif', "deskripsi_kegiatan" text, "dibuat_pada" datetime not null default CURRENT_TIMESTAMP, "diperbarui_pada" datetime not null default CURRENT_TIMESTAMP, foreign key("komisi_id") references "kormi_komisi_inorga"("id") on delete restrict, primary key ("id"));
CREATE TABLE IF NOT EXISTS "kormi_kategori_event" ("id" varchar not null, "nama_kategori" varchar not null, "slug" varchar not null, "dibuat_pada" datetime not null default CURRENT_TIMESTAMP, "diperbarui_pada" datetime not null default CURRENT_TIMESTAMP, primary key ("id"));
CREATE TABLE IF NOT EXISTS "kormi_event" ("id" varchar not null, "kategori_event_id" varchar not null, "judul_event" varchar not null, "slug" varchar not null, "tahun_edisi" integer not null, "lokasi_utama" varchar not null, "tanggal_mulai" date not null, "tanggal_selesai" date not null, "banner_url" varchar, "logo_event_url" varchar, "deskripsi_lengkap" text, "tautan_eksternal" varchar, "status_publikasi" tinyint(1) not null default '1', "dibuat_pada" datetime not null default CURRENT_TIMESTAMP, "diperbarui_pada" datetime not null default CURRENT_TIMESTAMP, foreign key("kategori_event_id") references "kormi_kategori_event"("id") on delete restrict, primary key ("id"));
CREATE TABLE IF NOT EXISTS "kormi_event_cabang" ("id" varchar not null, "event_id" varchar not null, "inorga_id" varchar, "nama_cabang" varchar not null, "kategori_peserta" varchar, "aturan_juknis_url" varchar, "ikon" varchar not null default 'award', "kode_warna_hex" varchar not null default 'bg-amber-500', "dibuat_pada" datetime not null default CURRENT_TIMESTAMP, "diperbarui_pada" datetime not null default CURRENT_TIMESTAMP, foreign key("event_id") references "kormi_event"("id") on delete cascade, foreign key("inorga_id") references "kormi_inorga"("id") on delete set null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "kormi_event_klasemen_medali" ("id" varchar not null, "event_id" varchar not null, "kecamatan_id" varchar not null, "jumlah_emas" integer not null default '0', "jumlah_perak" integer not null default '0', "jumlah_perunggu" integer not null default '0', "total_medali" integer not null default '0', "peringkat" integer not null default '0', "dibuat_pada" datetime not null default CURRENT_TIMESTAMP, "diperbarui_pada" datetime not null default CURRENT_TIMESTAMP, foreign key("event_id") references "kormi_event"("id") on delete cascade, foreign key("kecamatan_id") references "kormi_kecamatan"("id") on delete cascade, primary key ("id"));
CREATE TABLE IF NOT EXISTS "kormi_event_jadwal" ("id" varchar not null, "event_id" varchar not null, "fase_tahapan" varchar not null, "tanggal" date not null, "jam_mulai" time, "jam_selesai" time, "nama_kegiatan" varchar not null, "tempat_arena" varchar not null, "status_tahapan" varchar check ("status_tahapan" in ('selesai', 'berlangsung', 'akan_datang')) not null default 'akan_datang', "keterangan" varchar, "dibuat_pada" datetime not null default CURRENT_TIMESTAMP, "diperbarui_pada" datetime not null default CURRENT_TIMESTAMP, foreign key("event_id") references "kormi_event"("id") on delete cascade, primary key ("id"));
CREATE TABLE IF NOT EXISTS "kormi_apmo_tahun" ("id" varchar not null, "tahun" integer not null, "tema_acara" varchar, "tanggal_penganugerahan" date, "tempat_acara" varchar, "deskripsi" text, "dibuat_pada" datetime not null default CURRENT_TIMESTAMP, "diperbarui_pada" datetime not null default CURRENT_TIMESTAMP, primary key ("id"));
CREATE TABLE IF NOT EXISTS "kormi_apmo_penerima" ("id" varchar not null, "apmo_tahun_id" varchar not null, "kategori_penghargaan" varchar not null, "nama_penerima" varchar not null, "asal_lembaga_wilayah" varchar, "deskripsi_capaian" text not null, "foto_url" varchar, "urutan" integer not null default '0', "dibuat_pada" datetime not null default CURRENT_TIMESTAMP, "diperbarui_pada" datetime not null default CURRENT_TIMESTAMP, foreign key("apmo_tahun_id") references "kormi_apmo_tahun"("id") on delete cascade, primary key ("id"));
CREATE TABLE IF NOT EXISTS "kormi_sdi_program" ("id" varchar not null, "judul_program" varchar not null, "slug" varchar not null, "sasaran_peserta" varchar, "standar_kompetensi" text, "jenis_sertifikasi" varchar, "banner_url" varchar, "status_aktif" tinyint(1) not null default '1', "dibuat_pada" datetime not null default CURRENT_TIMESTAMP, "diperbarui_pada" datetime not null default CURRENT_TIMESTAMP, primary key ("id"));
CREATE TABLE IF NOT EXISTS "kormi_sdi_jadwal" ("id" varchar not null, "program_id" varchar not null, "nama_angkatan" varchar not null, "tanggal_mulai" date not null, "tanggal_selesai" date not null, "lokasi_pelatihan" varchar not null, "kuota_peserta" integer not null default '30', "jumlah_pendaftar" integer not null default '0', "status_pendaftaran" varchar check ("status_pendaftaran" in ('dibuka', 'berlangsung', 'selesai', 'penuh')) not null default 'dibuka', "dibuat_pada" datetime not null default CURRENT_TIMESTAMP, "diperbarui_pada" datetime not null default CURRENT_TIMESTAMP, foreign key("program_id") references "kormi_sdi_program"("id") on delete cascade, primary key ("id"));
CREATE TABLE IF NOT EXISTS "kormi_sdi_peserta" ("id" varchar not null, "jadwal_id" varchar not null, "kecamatan_id" varchar, "nama_lengkap" varchar not null, "nik" varchar, "nomor_telepon" varchar not null, "email" varchar, "asal_lembaga_inorga" varchar, "status_kelulusan" varchar check ("status_kelulusan" in ('menunggu', 'diverifikasi', 'lulus', 'tidak_lulus')) not null default 'menunggu', "nomor_sertifikat" varchar, "dibuat_pada" datetime not null default CURRENT_TIMESTAMP, "diperbarui_pada" datetime not null default CURRENT_TIMESTAMP, foreign key("jadwal_id") references "kormi_sdi_jadwal"("id") on delete cascade, foreign key("kecamatan_id") references "kormi_kecamatan"("id") on delete set null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "kormi_sapras" ("id" varchar not null, "kecamatan_id" varchar not null, "nama_fasilitas" varchar not null, "kategori_fasilitas" varchar not null, "alamat_lengkap" text not null, "kapasitas" varchar, "status_kondisi" varchar check ("status_kondisi" in ('Baik', 'Perlu Renovasi', 'Dalam Pembangunan')) not null default 'Baik', "jenis_olahraga_tersedia" varchar not null, "kontak_pengelola" varchar, "nomor_telepon" varchar, "latitude" numeric, "longitude" numeric, "foto_url" varchar, "dibuat_pada" datetime not null default CURRENT_TIMESTAMP, "diperbarui_pada" datetime not null default CURRENT_TIMESTAMP, foreign key("kecamatan_id") references "kormi_kecamatan"("id") on delete restrict, primary key ("id"));
CREATE TABLE IF NOT EXISTS "kormi_kategori_berita" ("id" varchar not null, "nama_kategori" varchar not null, "slug" varchar not null, "kode_warna_hex" varchar not null default '#1bb55c', "dibuat_pada" datetime not null default CURRENT_TIMESTAMP, "diperbarui_pada" datetime not null default CURRENT_TIMESTAMP, primary key ("id"));
CREATE TABLE IF NOT EXISTS "kormi_berita" ("id" varchar not null, "kategori_id" varchar not null, "penulis_id" varchar not null, "judul" varchar not null, "slug" varchar not null, "ringkasan" text not null, "isi_konten" text not null, "gambar_utama" varchar not null, "keterangan_gambar" varchar, "jumlah_dilihat" integer not null default '0', "status_unggulan" tinyint(1) not null default '0', "status_publikasi" varchar check ("status_publikasi" in ('draft', 'published', 'archived')) not null default 'draft', "tanggal_publikasi" datetime, "dibuat_pada" datetime not null default CURRENT_TIMESTAMP, "diperbarui_pada" datetime not null default CURRENT_TIMESTAMP, "dihapus_pada" datetime, foreign key("kategori_id") references "kormi_kategori_berita"("id") on delete restrict, foreign key("penulis_id") references "kormi_pengguna"("id") on delete restrict, primary key ("id"));
CREATE TABLE IF NOT EXISTS "kormi_galeri_album" ("id" varchar not null, "judul_album" varchar not null, "slug" varchar not null, "tanggal_kegiatan" date, "gambar_sampul" varchar, "deskripsi" text, "status_tampil" tinyint(1) not null default '1', "dibuat_pada" datetime not null default CURRENT_TIMESTAMP, "diperbarui_pada" datetime not null default CURRENT_TIMESTAMP, primary key ("id"));
CREATE TABLE IF NOT EXISTS "kormi_galeri_foto" ("id" varchar not null, "album_id" varchar not null, "judul_foto" varchar not null, "gambar_url" varchar not null, "keterangan_foto" text, "tipe_grid" varchar check ("tipe_grid" in ('normal', 'col-span-2 row-span-2', 'col-span-1 row-span-2', 'col-span-2 row-span-1')) not null default 'normal', "urutan" integer not null default '0', "dibuat_pada" datetime not null default CURRENT_TIMESTAMP, "diperbarui_pada" datetime not null default CURRENT_TIMESTAMP, foreign key("album_id") references "kormi_galeri_album"("id") on delete cascade, primary key ("id"));
CREATE TABLE IF NOT EXISTS "kormi_kategori_unduhan" ("id" varchar not null, "nama_kategori" varchar not null, "slug" varchar not null, "dibuat_pada" datetime not null default CURRENT_TIMESTAMP, "diperbarui_pada" datetime not null default CURRENT_TIMESTAMP, primary key ("id"));
CREATE TABLE IF NOT EXISTS "kormi_unduhan" ("id" varchar not null, "kategori_id" varchar not null, "pengunggah_id" varchar not null, "judul_dokumen" varchar not null, "berkas_path" varchar not null, "ekstensi_berkas" varchar not null, "ukuran_berkas" varchar not null, "nama_ikon" varchar not null default 'file-text', "jumlah_unduhan" integer not null default '0', "status_publik" tinyint(1) not null default '1', "dibuat_pada" datetime not null default CURRENT_TIMESTAMP, "diperbarui_pada" datetime not null default CURRENT_TIMESTAMP, "dihapus_pada" datetime, foreign key("kategori_id") references "kormi_kategori_unduhan"("id") on delete restrict, foreign key("pengunggah_id") references "kormi_pengguna"("id") on delete restrict, primary key ("id"));
CREATE TABLE IF NOT EXISTS "kormi_log_aktivitas" ("id" varchar not null, "pengguna_id" varchar, "jenis_aksi" varchar not null, "nama_tabel" varchar not null, "id_entitas" varchar, "data_lama" text, "data_baru" text, "alamat_ip" varchar, "agen_pengguna" varchar, "dibuat_pada" datetime not null default CURRENT_TIMESTAMP, foreign key("pengguna_id") references "kormi_pengguna"("id") on delete set null, primary key ("id"));
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE UNIQUE INDEX "kormi_peran_slug_unique" on "kormi_peran" ("slug");
CREATE UNIQUE INDEX "kormi_pengguna_email_unique" on "kormi_pengguna" ("email");
CREATE UNIQUE INDEX "kormi_pengaturan_situs_kunci_pengaturan_unique" on "kormi_pengaturan_situs" ("kunci_pengaturan");
CREATE UNIQUE INDEX "kormi_kecamatan_slug_unique" on "kormi_kecamatan" ("slug");
CREATE UNIQUE INDEX "kormi_desa_kelurahan_kecamatan_id_slug_unique" on "kormi_desa_kelurahan" ("kecamatan_id", "slug");
CREATE UNIQUE INDEX "kormi_komisi_inorga_singkatan_unique" on "kormi_komisi_inorga" ("singkatan");
CREATE UNIQUE INDEX "kormi_inorga_slug_unique" on "kormi_inorga" ("slug");
CREATE UNIQUE INDEX "kormi_kategori_event_slug_unique" on "kormi_kategori_event" ("slug");
CREATE UNIQUE INDEX "kormi_event_slug_unique" on "kormi_event" ("slug");
CREATE UNIQUE INDEX "kormi_event_klasemen_medali_event_id_kecamatan_id_unique" on "kormi_event_klasemen_medali" ("event_id", "kecamatan_id");
CREATE UNIQUE INDEX "kormi_apmo_tahun_tahun_unique" on "kormi_apmo_tahun" ("tahun");
CREATE UNIQUE INDEX "kormi_sdi_program_slug_unique" on "kormi_sdi_program" ("slug");
CREATE UNIQUE INDEX "kormi_kategori_berita_slug_unique" on "kormi_kategori_berita" ("slug");
CREATE UNIQUE INDEX "kormi_berita_slug_unique" on "kormi_berita" ("slug");
CREATE UNIQUE INDEX "kormi_galeri_album_slug_unique" on "kormi_galeri_album" ("slug");
CREATE UNIQUE INDEX "kormi_kategori_unduhan_slug_unique" on "kormi_kategori_unduhan" ("slug");
COMMIT;
