INSERT INTO kormi_kategori_berita VALUES('a2b3cd3e-b8f1-423f-983b-305a4f37c074','Sosial','sosial','#ec4899','2026-09-09 05:21:02','2026-09-09 05:21:02');
INSERT INTO kormi_berita VALUES('a2b3cd3e-b970-4747-8871-c277ae412f1e','a2b3cd3e-b7fe-410a-a535-b1b8592674d4','a2b3cd3e-87a2-4c16-bb6c-e78cd62a7682','Persiapan Menuju FORKAB 2026: Rapat Koordinasi Wilayah','persiapan-menuju-forkab-2026-rapat-koordinasi-wilayah','KORMI Kabupaten Bandung melakukan sinkronisasi program kerja bersama seluruh pengurus kecamatan untuk mempersiapkan FORKAB 2026 yang akan segera diselenggarakan.','<p>KORMI Kabupaten Bandung menyelenggarakan rapat koordinasi wilayah untuk mematangkan kesiapan pelaksanaan Festival Olahraga Rekreasi Masyarakat Kabupaten (FORKAB) 2026. Pertemuan yang dihadiri oleh seluruh koordinator kecamatan dan pimpinan induk organisasi olahraga (INORGA) ini bertujuan menyelaraskan teknis perlombaan dan kesiapan kontingen dari 31 kecamatan.</p><p>Ketua KORMI Kabupaten Bandung menyampaikan bahwa FORKAB tahun ini akan mengusung semangat kolaborasi dan kebugaran inklusif untuk seluruh lapisan masyarakat Kabupaten Bandung.</p>','https://images.unsplash.com/photo-1517649763962-0c623066013b?q=80&w=800',NULL,1256,1,'published','2026-09-07 05:21:02','2026-09-09 05:21:02','2026-09-09 05:48:47',NULL);
INSERT INTO kormi_berita VALUES('a2b3cd3e-b99e-4f18-b9c4-cb749f9f0e28','a2b3cd3e-b827-43f3-ac87-5751935a5d45','a2b3cd3e-87a2-4c16-bb6c-e78cd62a7682','Atlet Inorga Kabupaten Bandung Raih Emas di Kejuaraan Nasional','atlet-inorga-kabupaten-bandung-raih-emas-di-kejuaraan-nasional','Kebanggaan bagi warga Bandung, perwakilan atlet tradisional kita berhasil menyabet podium utama di ajang nasional.','<p>Prestasi membanggakan kembali diukir oleh atlet olahraga rekreasi Kabupaten Bandung pada ajang Kejuaraan Tingkat Nasional. Delegasi berhasil membawa pulang medali emas setelah unggul di kategori ketangkasan dan olahraga tradisional.</p>','https://images.unsplash.com/photo-1526676023641-72e042776856?q=80&w=800',NULL,870,0,'published','2026-09-04 05:21:02','2026-09-09 05:21:02','2026-09-09 05:21:02',NULL);
INSERT INTO kormi_berita VALUES('a2b3cd3e-b9c9-455a-9e59-e09c53d0d9d9','a2b3cd3e-b84e-40e6-8670-95f876c5c746','a2b3cd3e-87a2-4c16-bb6c-e78cd62a7682','Senam Massal Bedas di Soreang: Ribuan Warga Turut Memeriahkan','senam-massal-bedas-di-soreang-ribuan-warga-turut-memeriahkan','Peningkatan indeks kebugaran masyarakat menjadi target utama dalam kegiatan rutin mingguan ini yang diikuti ribuan peserta.','<p>Ribuan warga memadati area Lapangan Upakarti Soreang untuk mengikuti Senam Massal Bedas. Kegiatan ini merupakan bagian dari gerakan pembudayaan olahraga yang digelorakan KORMI bekerjasama dengan ASIAFI dan STI.</p>','https://images.unsplash.com/photo-1571019613454-1cb2f99b2d8b?q=80&w=800',NULL,1520,0,'published','2026-09-01 05:21:02','2026-09-09 05:21:02','2026-09-09 05:21:02',NULL);
INSERT INTO kormi_berita VALUES('a2b3cd3e-b9f2-44ab-ab02-c7ed650d673c','a2b3cd3e-b883-4303-b3bf-3487896a0c22','a2b3cd3e-87a2-4c16-bb6c-e78cd62a7682','Audiensi KORMI Bersama Bupati Bandung Bahas Masa Depan Olahraga','audiensi-kormi-bersama-bupati-bandung-bahas-masa-depan-olahraga','Pertemuan strategis untuk memperkuat dukungan pemerintah daerah terhadap olahraga rekreasi masyarakat.','<p>Jajaran pengurus KORMI Kabupaten Bandung diterima langsung oleh Bupati Bandung di Rumah Dinas Soreang. Pertemuan ini membahas rencana penguatan infrastruktur olahraga masyarakat serta pendukungan anggaran untuk pembinaan 31 kecamatan.</p>','https://images.unsplash.com/photo-1542744173-8e7e53415bb0?q=80&w=800',NULL,960,0,'published','2026-08-30 05:21:02','2026-09-09 05:21:02','2026-09-09 05:21:02',NULL);
INSERT INTO kormi_berita VALUES('a2b3cd3e-ba46-4ecb-a797-cd883380abdb','a2b3cd3e-b8bc-4290-a54a-7c1acb29c300','a2b3cd3e-87a2-4c16-bb6c-e78cd62a7682','Pelatihan Pelatih Olahraga Tradisional Tingkat Kabupaten Bandung','pelatihan-pelatih-olahraga-tradisional-tingkat-kabupaten-bandung','Mencetak instruktur yang kompeten untuk melestarikan budaya olahraga asli daerah di setiap kecamatan.','<p>Sebanyak 60 calon pelatih olahraga tradisional mengikuti sertifikasi dan bimbingan teknis PORTINA untuk meningkatkan standar perwasitan dan kepelatihan egrang, terompah panjang, dan hadang.</p>','https://images.unsplash.com/photo-1552664730-d307ca884978?q=80&w=800',NULL,640,0,'published','2026-08-28 05:21:02','2026-09-09 05:21:02','2026-09-09 05:21:02',NULL);
INSERT INTO kormi_berita VALUES('a2b3cd3e-ba87-42b8-a97f-16440e916969','a2b3cd3e-b8f1-423f-983b-305a4f37c074','a2b3cd3e-87a2-4c16-bb6c-e78cd62a7682','Bakti Sosial KORMI Berbagi: Sehat Raganya, Bahagia Jiwanya','bakti-sosial-kormi-berbagi-sehat-raganya-bahagia-jiwanya','Kegiatan kolaboratif antara olahraga dan kepedulian sosial di wilayah terdampak bencana alam.','<p>KORMI menyalurkan bantuan paket logistik sekaligus mengadakan terapi senam bugar untuk warga terdampak di wilayah Kabupaten Bandung selatan.</p>','https://images.unsplash.com/photo-1506190506097-31133f7d3f97?q=80&w=800',NULL,510,0,'published','2026-08-25 05:21:02','2026-09-09 05:21:02','2026-09-09 05:21:02',NULL);
INSERT INTO kormi_berita VALUES('a2b3cd3e-baff-45c8-b847-3000931c0e3c','a2b3cd3e-b7fe-410a-a535-b1b8592674d4','a2b3cd3e-87a2-4c16-bb6c-e78cd62a7682','Bandung Bedas Run 2026: Pendaftaran Resmi Dibuka!','bandung-bedas-run-2026-pendaftaran-resmi-dibuka','Event lari terbesar di Kabupaten Bandung kembali hadir. Segera daftarkan diri Anda dan raihlah pengalaman berlari terbaik.','<p>Pendaftaran Bandung Bedas Run 2026 kategori 5K dan 10K resmi dibuka. Rute akan melintasi ikon-ikon pariwisata Soreang dan Stadion Si Jalak Harupat.</p>','https://images.unsplash.com/photo-1461896836934-bd45ba0fcf5b?q=80&w=800',NULL,2100,0,'published','2026-08-22 05:21:02','2026-09-09 05:21:02','2026-09-09 05:21:02',NULL);
INSERT INTO kormi_berita VALUES('a2b3cd3e-bb46-4843-a67e-0f02619a0b05','a2b3cd3e-b827-43f3-ac87-5751935a5d45','a2b3cd3e-87a2-4c16-bb6c-e78cd62a7682','Kecamatan Margahayu Juara Umum FOTRADKAB 2025','kecamatan-margahayu-juara-umum-fotradkab-2025','Dengan perolehan 10 emas, 6 perak, dan 4 perunggu, Margahayu keluar sebagai juara umum FOTRADKAB tahun ini.','<p>Dominasi kontingen Margahayu di cabang hadang dan ketapel berhasil mengantarkan mereka mengukuhkan gelar Juara Umum FOTRADKAB.</p>','https://images.unsplash.com/photo-1526676037777-05a232554f77?q=80&w=800',NULL,1180,0,'published','2026-08-20 05:21:02','2026-09-09 05:21:02','2026-09-09 05:21:02',NULL);
